        partial void CustomFactoryEnd(
            OverlayStream stream,
            int finalPos,
            int offset);

        partial void CustomCtor();
        protected MainFileHeaderBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static IMainFileHeaderGetter MainFileHeaderFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new MainFileHeaderBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IMainFileHeaderGetter MainFileHeaderFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return MainFileHeaderFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.MMSB:
                {
                    _MMSBLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.MMSB;
                }
                case RecordTypeInts.CNAM:
                {
                    _CNAMLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.CNAM;
                }
                case RecordTypeInts.SNAM:
                {
                    _SNAMLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.SNAM;
                }
                case RecordTypeInts.DATA:
                {
                    this.MasterFiles = BinaryOverlayList.FactoryByArray<ReadOnlyMemorySlice<Byte>>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        getter: (s, p) => p.MetaData.Constants.Subrecord(s).Content,
                        locs: ParseRecordLocations(
                            stream: stream,
                            constants: _package.MetaData.Constants.SubConstants,
                            trigger: RecordTypes.DATA,
                            skipHeader: false,
                            translationParams: translationParams));
                    return (int)MainFileHeader_FieldIndex.MasterFiles;
                }
                case RecordTypeInts.ONAM:
                {
                    _ONAMLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.ONAM;
                }
                case RecordTypeInts.INTV:
                {
                    _INTVLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.INTV;
                }
                case RecordTypeInts.INCC:
                {
                    _INCCLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.INCC;
                }
                case RecordTypeInts.DELE:
                {
                    _DELELocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.DELE;
                }
                case RecordTypeInts.OFST:
                {
                    _OFSTLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.OFST;
                }
                case RecordTypeInts.SCRN:
                {
                    _SCRNLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.SCRN;
                }
                case RecordTypeInts.TNAM:
                {
                    _TNAMLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.TNAM;
                }
                case RecordTypeInts.HEDR:
                {
                    _HEDRLocation = (stream.Position - offset);
                    return (int)MainFileHeader_FieldIndex.HEDR;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
